// AdminServiceHandler is an implementation of the heron.v1.AdminService service.
type AdminServiceHandler interface {
	// 预览和执行共用业务校验。执行需 request_id；修改已有资源必须提供预览的 expected_version。
	// 同一主体和 request_id 只提交一次；重试返回回执，result 为空，不重放一次性秘密。
	ExecuteChange(context.Context, *connect.Request[v1.ExecuteChangeRequest]) (*connect.Response[v1.ExecuteChangeResponse], error)
	// API token 只能查询自己的回执；会话可指定 owner_id。回执不含凭据。
	ListOperations(context.Context, *connect.Request[v1.ListOperationsRequest]) (*connect.Response[v1.ListOperationsResponse], error)
	// 仅返回渠道 id、名称和类型，不含地址、模板和密钥。
	ListNotifyChannelRefs(context.Context, *connect.Request[v1.ListNotifyChannelRefsRequest]) (*connect.Response[v1.ListNotifyChannelRefsResponse], error)
	// 读取 hub 与节点的更新能力和最新任务。检查官方版本需显式 check_latest。
	GetUpdates(context.Context, *connect.Request[v1.GetUpdatesRequest]) (*connect.Response[v1.GetUpdatesResponse], error)
	// 创建单目标更新。node_id=0 为 hub，目标须是比 hub 当前版本新的官方正式版；节点的目标须等于
	// GetUpdatesResponse.bound_agent_version 且比节点当前版本新；已出租的节点不能更新。
	// 节点离线时排队，24 小时过期；同一目标不能同时有多个活动任务。
	StartUpdate(context.Context, *connect.Request[v1.StartUpdateRequest]) (*connect.Response[v1.StartUpdateResponse], error)
	// 仅可取消尚未下发的 queued 节点任务；已下发或 hub 任务不能取消。
	CancelUpdate(context.Context, *connect.Request[v1.CancelUpdateRequest]) (*connect.Response[v1.CancelUpdateResponse], error)
	// 用管理员密码换取会话 cookie（Set-Cookie 在响应头里）。
	Login(context.Context, *connect.Request[v1.LoginRequest]) (*connect.Response[v1.LoginResponse], error)
	// 发起无密码 Passkey 登录；挑战只可消费一次。
	BeginPasskeyLogin(context.Context, *connect.Request[v1.BeginPasskeyLoginRequest]) (*connect.Response[v1.BeginPasskeyLoginResponse], error)
	FinishPasskeyLogin(context.Context, *connect.Request[v1.FinishPasskeyLoginRequest]) (*connect.Response[v1.FinishPasskeyLoginResponse], error)
	// 安全凭据仅允许会话访问，不返回 TOTP 密钥或恢复码。
	GetSecurity(context.Context, *connect.Request[v1.GetSecurityRequest]) (*connect.Response[v1.GetSecurityResponse], error)
	// 修改凭据需要重新认证；挑战绑定当前会话与凭据版本。修改成功撤销现有会话。
	SecurityAction(context.Context, *connect.Request[v1.SecurityActionRequest]) (*connect.Response[v1.SecurityActionResponse], error)
	// 作废当前会话并清除 cookie。
	Logout(context.Context, *connect.Request[v1.LogoutRequest]) (*connect.Response[v1.LogoutResponse], error)
	// 列出未绝对过期且未空闲过期的会话，按创建时刻倒序、同刻按 id 升序。
	// API token 不能管理其它凭据，因此不能列出或撤销会话。
	ListSessions(context.Context, *connect.Request[v1.ListSessionsRequest]) (*connect.Response[v1.ListSessionsResponse], error)
	// 撤销指定会话；撤销当前会话时同时清 cookie，等同登出。
	// 不存在或已过期的 id 也成功，便于在响应丢失后安全重试；撤销的若是本次请求所用的会话，
	// 第一次请求已在服务端删掉这一行，带同一 cookie 重试会得到 Unauthenticated 而非再次成功——
	// 会话已不存在，结果仍安全。
	RevokeSession(context.Context, *connect.Request[v1.RevokeSessionRequest]) (*connect.Response[v1.RevokeSessionResponse], error)
	// 列出节点；可按标签过滤（ListNodesRequest.tags），或只列无标签节点（ListNodesRequest.untagged）。
	ListNodes(context.Context, *connect.Request[v1.ListNodesRequest]) (*connect.Response[v1.ListNodesResponse], error)
	// 建节点（默认公开，可带 rented）并返回一次性安装凭据；明文只在此处返回一次，须经 AgentService.Register 换成运行 token，不能直接上报。
	// 新节点继承全部 all_nodes 探测任务，它们多于每节点上限（64）时
	// 返回 ResourceExhausted 并说明，节点不建。
	CreateNode(context.Context, *connect.Request[v1.CreateNodeRequest]) (*connect.Response[v1.CreateNodeResponse], error)
	// 整体替换可编辑字段（名称、是否公开、备注、周期重置日、离线宽限期、计费与到期、国家、标签、维护状态、已出租状态）。计费字段有变化时，
	// 返回之前按新值做一次到期扫描（自动续期推后、到期规则评估），响应里的到期日与 days_left 是扫描之后的值。
	UpdateNode(context.Context, *connect.Request[v1.UpdateNodeRequest]) (*connect.Response[v1.UpdateNodeResponse], error)
	// 把节点的到期日按计费周期推后，用于"已续费"：与自动续期同一推后规则（见 store.Billing）——先推后一个周期，仍早于 hub 时区
	// （--timezone）的今天就继续按周期推后，直到不早于今天。未过期的节点恰好推后一个周期；已过期的与自动续期落在同一天，
	// 保留账单日，过期多个周期的一次跳过；日号超过目标月天数时钳到月末。不要求开着自动续期。节点没有周期或没有到期日返回 InvalidArgument 并点名缺的字段；hub 读到的周期
	// 与到期日在写入时已被并发修改返回 FailedPrecondition，刷新后重试。写入后与 UpdateNode 一样做一次到期扫描，
	// 响应里的到期日与 days_left 是扫描之后的值。API token 经 ExecuteChange 的 renew_node_billing 调用。
	RenewNodeBilling(context.Context, *connect.Request[v1.RenewNodeBillingRequest]) (*connect.Response[v1.RenewNodeBillingResponse], error)
	// 原子修改指定节点的标签关联，不覆盖其它标签或节点字段；成功时同步刷新探测与告警的动态覆盖。
	// 任一节点不存在返回 NotFound；标签超限返回 InvalidArgument，探测任务超限返回 ResourceExhausted，整批回滚。
	BatchUpdateNodeTags(context.Context, *connect.Request[v1.BatchUpdateNodeTagsRequest]) (*connect.Response[v1.BatchUpdateNodeTagsResponse], error)
	// 删除节点及其全部历史；进程内的实时状态同步清理。
	DeleteNode(context.Context, *connect.Request[v1.DeleteNodeRequest]) (*connect.Response[v1.DeleteNodeResponse], error)
	// 撤销旧凭据并换发一次性安装凭据；须经 AgentService.Register 换成运行 token，不能直接上报。
	// 已安装主机用安装脚本的 --re-register 显式替换注册，普通升级不消费此凭据。
	RotateNodeToken(context.Context, *connect.Request[v1.RotateNodeTokenRequest]) (*connect.Response[v1.RotateNodeTokenResponse], error)
	// 给出全部节点 id 的新顺序；必须恰好包含每个节点一次。
	ReorderNodes(context.Context, *connect.Request[v1.ReorderNodesRequest]) (*connect.Response[v1.ReorderNodesResponse], error)
	// 把一组节点按它们现有的先后整体移到全序第 position 位起的连续位置，其余节点相对顺序不变。全序按
	// (sort_order, id) 升序，与列表、总览、公开页同一顺序；Node.position 是节点在这条全序里的名次（从 1 起，
	// 不随标签过滤、搜索或调用方可见的节点范围变化），position 与它同一编号。ids 里的节点按现有先后占据
	// 第 position..position+k-1 位（k 为去重后的节点数），原第 position 位起的其余节点依次后移；被选节点
	// 原本就排在目标位置之前的同样适用。ids 至少一个（空列表返回 InvalidArgument）；重复 id 去重；请求里
	// id 的先后不影响结果；任一 id 不存在返回 NotFound 并给出该 id，整批不改。position 合法区间
	// 1..N-k+1（N 为节点总数），越界返回 InvalidArgument 并写明区间，不截断——截断会让写错的位置静默落到首尾。
	MoveNodes(context.Context, *connect.Request[v1.MoveNodesRequest]) (*connect.Response[v1.MoveNodesResponse], error)
	// 全部标签与各自挂在几个节点上，按名字大小写不敏感排序；没挂在任何节点上的标签也在内（节点数 0）。
	ListTags(context.Context, *connect.Request[v1.ListTagsRequest]) (*connect.Response[v1.ListTagsResponse], error)
	// 删除标签：被探测或告警动态选择器引用时拒绝；否则解除节点关联并删除。名字大小写不敏感；不存在时 NotFound。
	DeleteTag(context.Context, *connect.Request[v1.DeleteTagRequest]) (*connect.Response[v1.DeleteTagResponse], error)
	// 开启（或替换）注册窗口，返回一次性 key。
	OpenRegisterWindow(context.Context, *connect.Request[v1.OpenRegisterWindowRequest]) (*connect.Response[v1.OpenRegisterWindowResponse], error)
	CloseRegisterWindow(context.Context, *connect.Request[v1.CloseRegisterWindowRequest]) (*connect.Response[v1.CloseRegisterWindowResponse], error)
	GetRegisterWindow(context.Context, *connect.Request[v1.GetRegisterWindowRequest]) (*connect.Response[v1.GetRegisterWindowResponse], error)
	// 全部节点的实时状态，供轮询；轮询间隔不必短于 report_interval_ms。
	GetSnapshot(context.Context, *connect.Request[v1.GetSnapshotRequest]) (*connect.Response[v1.GetSnapshotResponse], error)
	// 某节点一段时间的历史；级别与步长由 hub 按窗口选定并随数据返回。
	QueryMetrics(context.Context, *connect.Request[v1.QueryMetricsRequest]) (*connect.Response[v1.QueryMetricsResponse], error)
	// 全部节点的流量：hub 累计的总量、当前周期用量、周期起点与下次重置时刻。
	GetTraffic(context.Context, *connect.Request[v1.GetTrafficRequest]) (*connect.Response[v1.GetTrafficResponse], error)
	// 把某节点当前周期的用量覆盖为给定值；总量按同一差值调整且不低于 0，计数器基线不动。
	AdjustTraffic(context.Context, *connect.Request[v1.AdjustTrafficRequest]) (*connect.Response[v1.AdjustTrafficResponse], error)
	// 按展示顺序列出全部探测任务及其分配。
	ListProbeTasks(context.Context, *connect.Request[v1.ListProbeTasksRequest]) (*connect.Response[v1.ListProbeTasksResponse], error)
	// 保存探测任务：id 为 0 即创建，提交整份分配列表。
	SaveProbeTask(context.Context, *connect.Request[v1.SaveProbeTaskRequest]) (*connect.Response[v1.SaveProbeTaskResponse], error)
	// 删除探测任务：不删历史，到期由清理删除。
	DeleteProbeTask(context.Context, *connect.Request[v1.DeleteProbeTaskRequest]) (*connect.Response[v1.DeleteProbeTaskResponse], error)
	// 整体重排探测任务的展示顺序，不改变 agent 执行清单或任务版本。
	ReorderProbeTasks(context.Context, *connect.Request[v1.ReorderProbeTasksRequest]) (*connect.Response[v1.ReorderProbeTasksResponse], error)
	// 某节点在窗口内全部任务的探测历史，选级与对齐规则同 QueryMetrics。
	QueryProbes(context.Context, *connect.Request[v1.QueryProbesRequest]) (*connect.Response[v1.QueryProbesResponse], error)
	// 跨节点对比的第一步：当前分配了该任务、且调用方可见的节点与任务标注。节点范围与标注规则同 QueryProbes。
	ListProbeComparisonNodes(context.Context, *connect.Request[v1.ListProbeComparisonNodesRequest]) (*connect.Response[v1.ListProbeComparisonNodesResponse], error)
	// 跨节点对比的第二步：一个任务在一组节点上的探测历史，节点按 ListProbeComparisonNodes 给出的上限分块。
	QueryProbeComparison(context.Context, *connect.Request[v1.QueryProbeComparisonRequest]) (*connect.Response[v1.QueryProbeComparisonResponse], error)
	// 一个探测任务在各节点上的证书观测：当前配置身份下的成功证书与信任候选，以及各节点钉指纹的能力状态。
	// 受限 token 只看其范围内的节点，且任务须是它可标注的任务，否则与任务不存在同一 NotFound。
	ListProbeCertificates(context.Context, *connect.Request[v1.ListProbeCertificatesRequest]) (*connect.Response[v1.ListProbeCertificatesResponse], error)
	// 列出规则及其当前节点状态。
	ListAlertRules(context.Context, *connect.Request[v1.ListAlertRulesRequest]) (*connect.Response[v1.ListAlertRulesResponse], error)
	// id 为 0 时创建，否则整体替换规则与作用域、渠道列表。
	SaveAlertRule(context.Context, *connect.Request[v1.SaveAlertRuleRequest]) (*connect.Response[v1.SaveAlertRuleResponse], error)
	// 删除规则与状态；事件与投递记录随规则删除保留；保留期见维护任务。
	DeleteAlertRule(context.Context, *connect.Request[v1.DeleteAlertRuleRequest]) (*connect.Response[v1.DeleteAlertRuleResponse], error)
	// 列出全部静默（含保留期内已过期的一次性静默），每条带此刻是否在窗口内与展开后的节点覆盖。
	ListSilences(context.Context, *connect.Request[v1.ListSilencesRequest]) (*connect.Response[v1.ListSilencesResponse], error)
	// id 为 0 时创建，否则整体替换静默与作用域。
	SaveSilence(context.Context, *connect.Request[v1.SaveSilenceRequest]) (*connect.Response[v1.SaveSilenceResponse], error)
	DeleteSilence(context.Context, *connect.Request[v1.DeleteSilenceRequest]) (*connect.Response[v1.DeleteSilenceResponse], error)
	// 按事件 id 倒序分页，包含每个事件的投递状态；投递失败只给类别与状态码，原文见 GetAlertDeliveryError。
	ListAlertEvents(context.Context, *connect.Request[v1.ListAlertEventsRequest]) (*connect.Response[v1.ListAlertEventsResponse], error)
	// 一次投递最近一次失败的原文：HTTP 失败时是响应体的前 200 个字符，其余是出站错误文本。hub 不把 URL
	// 写进原文，但响应体由接收方决定：接收方若回显请求路径或头值，这些只写不读的配置也会出现在这里，
	// 这在会话的权限之内。
	// 接收方可能在错误响应里回显收到的请求体，而 webhook 请求体模板里可能放着密钥，所以只对会话开放。
	// 投递不存在时返回 NotFound；没有失败、或类别没有原文时返回空串。
	GetAlertDeliveryError(context.Context, *connect.Request[v1.GetAlertDeliveryErrorRequest]) (*connect.Response[v1.GetAlertDeliveryErrorResponse], error)
	// 不回显凭据本身，但请求体模板、URL 主机名与头名称会回显，模板里可能放着密钥。
	// agent 不需要渠道配置，所以只对会话开放。
	ListNotifyChannels(context.Context, *connect.Request[v1.ListNotifyChannelsRequest]) (*connect.Response[v1.ListNotifyChannelsResponse], error)
	// id 为 0 创建，否则替换；凭据字段为空或省略时保留旧值，删除头用 remove_headers。
	SaveNotifyChannel(context.Context, *connect.Request[v1.SaveNotifyChannelRequest]) (*connect.Response[v1.SaveNotifyChannelResponse], error)
	// 被告警规则引用的渠道不可删除，错误列出引用规则。
	DeleteNotifyChannel(context.Context, *connect.Request[v1.DeleteNotifyChannelRequest]) (*connect.Response[v1.DeleteNotifyChannelResponse], error)
	// 向已保存的渠道同步发送测试消息；不可重试失败返回 FailedPrecondition，可重试返回 Unavailable，文本为错误原文。
	TestNotifyChannel(context.Context, *connect.Request[v1.TestNotifyChannelRequest]) (*connect.Response[v1.TestNotifyChannelResponse], error)
	// 公开页设置（总闸与外观）、国家查询、备份与登录通知设置；外观在总闸开启时经 PublicService.GetSite 对外下发。
	GetSettings(context.Context, *connect.Request[v1.GetSettingsRequest]) (*connect.Response[v1.GetSettingsResponse], error)
	// 两层备份的成功时刻与当前进程观察到的故障；不返回目标凭据或远端错误原文。
	GetBackupStatus(context.Context, *connect.Request[v1.GetBackupStatusRequest]) (*connect.Response[v1.GetBackupStatusResponse], error)
	// 离线恢复（heron-hub restore）写下的恢复记录，按恢复时刻倒序、同刻按 id 升序；恢复只在停机时发生，
	// 记录随配置层备份并按 id 与目标库已有的取并集，没有删除路径，是审计历史而非状态。
	ListRestoreRecords(context.Context, *connect.Request[v1.ListRestoreRecordsRequest]) (*connect.Response[v1.ListRestoreRecordsResponse], error)
	// hub 心跳外推的当前状态：是否已配置、上次成功与上次失败的时刻与类别、下次外呼时刻。
	// 状态只在进程内存里，重启后"从未跑过"的两者都为 0；目标地址是只写设置，不在这里也不在 GetSettings 回显。
	GetHeartbeatStatus(context.Context, *connect.Request[v1.GetHeartbeatStatusRequest]) (*connect.Response[v1.GetHeartbeatStatusResponse], error)
	// 按组更新设置（分组与判定见 Settings）：给出的外观整体替换，给出的总闸、国家查询项、backup 与 login_notify 写入，
	// 缺席的组不变；回显 hub 实际保存的设置。一组都没给出、或任一项不合约束即 InvalidArgument，错误写明字段、约束与
	// 期望取值，什么都不写入。
	UpdateSettings(context.Context, *connect.Request[v1.UpdateSettingsRequest]) (*connect.Response[v1.UpdateSettingsResponse], error)
	// 主题在同域的受限沙箱运行，安装与启用分离。
	// 上传一个主题包（zip，至多 8 MiB）并安装不可变版本，不改变当前公开页。
	// 包的约束（条目数、展开大小、条目类型与路径、清单字段）见 UploadThemeRequest；任一不满足即 InvalidArgument，
	// 错误写明条目或字段与原因，什么都不写入。主题数已满（20）且 id 是新的时 ResourceExhausted。
	UploadTheme(context.Context, *connect.Request[v1.UploadThemeRequest]) (*connect.Response[v1.UploadThemeResponse], error)
	// 已安装的主题，按 id 升序。
	ListThemes(context.Context, *connect.Request[v1.ListThemesRequest]) (*connect.Response[v1.ListThemesResponse], error)
	// 启用指定摘要的主题版本；id 为空即切回内置公开页。
	// 没有这个主题时 NotFound，启用状态不变。
	EnableTheme(context.Context, *connect.Request[v1.EnableThemeRequest]) (*connect.Response[v1.EnableThemeResponse], error)
	// 删除主题及其全部文件；删的是启用中的主题时回落到内置公开页。没有这个主题时 NotFound。
	DeleteTheme(context.Context, *connect.Request[v1.DeleteThemeRequest]) (*connect.Response[v1.DeleteThemeResponse], error)
	// 主题清单 preview 指向的预览图。主题不存在或清单没有给 preview 时 NotFound。
	GetThemePreview(context.Context, *connect.Request[v1.GetThemePreviewRequest]) (*connect.Response[v1.GetThemePreviewResponse], error)
	// 删除未使用版本，不允许删除当前或上一回滚版本。
	DeleteThemeVersion(context.Context, *connect.Request[v1.DeleteThemeVersionRequest]) (*connect.Response[v1.DeleteThemeVersionResponse], error)
	// 读取公开 GitHub 仓库的 Release 列表，不安装任何内容。
	ListThemeReleases(context.Context, *connect.Request[v1.ListThemeReleasesRequest]) (*connect.Response[v1.ListThemeReleasesResponse], error)
	// 安装明确选定的 Release ZIP 资产；不执行源码构建，不自动启用。
	InstallThemeRelease(context.Context, *connect.Request[v1.InstallThemeReleaseRequest]) (*connect.Response[v1.InstallThemeReleaseResponse], error)
	// 为当前会话创建短期交互预览；不会公开或启用该版本。
	PreviewTheme(context.Context, *connect.Request[v1.PreviewThemeRequest]) (*connect.Response[v1.PreviewThemeResponse], error)
	// 下载保留的原始 ZIP；旧 SDK 归档也可下载，但不因此取得执行权限。
	GetThemePackage(context.Context, *connect.Request[v1.GetThemePackageRequest]) (*connect.Response[v1.GetThemePackageResponse], error)
	// 库的逻辑大小、每张表的行数与存储健康读数，与 heron-hub stats 同一来源。
	GetStorageStats(context.Context, *connect.Request[v1.GetStorageStatsRequest]) (*connect.Response[v1.GetStorageStatsResponse], error)
	// API token 的元数据；明文只在 CreateApiToken 的响应里出现一次，hub 只存哈希。
	ListApiTokens(context.Context, *connect.Request[v1.ListApiTokensRequest]) (*connect.Response[v1.ListApiTokensResponse], error)
	// 建一个只读 API token，以 Authorization: Bearer <token> 调用 ACCESS_READ 方法。
	CreateApiToken(context.Context, *connect.Request[v1.CreateApiTokenRequest]) (*connect.Response[v1.CreateApiTokenResponse], error)
	// 吊销：下一个用它的请求即返回 Unauthenticated，不需要重启 hub。
	DeleteApiToken(context.Context, *connect.Request[v1.DeleteApiTokenRequest]) (*connect.Response[v1.DeleteApiTokenResponse], error)
	// 技能文件与 hub 构建时嵌入的全部 proto 源文件：不在仓库里的调用方由此取得与 hub 同版本的 schema。
	GetApiReference(context.Context, *connect.Request[v1.GetApiReferenceRequest]) (*connect.Response[v1.GetApiReferenceResponse], error)
}

